CREATE TABLE ingestion_runs(id UUID PRIMARY KEY,run_type VARCHAR(16) NOT NULL CHECK(run_type IN('SCHEDULED','BACKFILL')),status VARCHAR(20) NOT NULL CHECK(status IN('RUNNING','CANCEL_REQUESTED','SUCCEEDED','FAILED','CANCELLED')),window_start TIMESTAMPTZ NOT NULL,window_end TIMESTAMPTZ NOT NULL CHECK(window_end>window_start),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,records_read BIGINT NOT NULL DEFAULT 0,events_written BIGINT NOT NULL DEFAULT 0,error_code VARCHAR(80),error_message VARCHAR(500));
CREATE UNIQUE INDEX one_active_ingestion_run ON ingestion_runs((true)) WHERE status IN('RUNNING','CANCEL_REQUESTED');
CREATE INDEX ingestion_history_idx ON ingestion_runs(started_at DESC,id);
CREATE TABLE market_price_events(event_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES ingestion_runs(id),provider VARCHAR(80) NOT NULL,delivery_start TIMESTAMPTZ NOT NULL,delivery_end TIMESTAMPTZ NOT NULL,price_gbp_mwh NUMERIC(19,6) NOT NULL,source_revision VARCHAR(100) NOT NULL,source_timestamp TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,last_error VARCHAR(1000),UNIQUE(provider,delivery_start,source_revision));
CREATE INDEX market_events_unpublished_idx ON market_price_events(occurred_at,event_id) WHERE published_at IS NULL;
